package com.example.splitstory;
import android.content.*;import android.security.keystore.*;import android.util.Base64;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.*;import java.security.cert.X509Certificate;import java.util.*;import javax.crypto.*;import javax.crypto.spec.*;
/** Existing exported games retain their Keystore signer. New games use a backed-up portable signer. */
final class CreatorSigning {
final Context context;final File folder;final SharedPreferences prefs;CreatorSigning(Context c){context=c;folder=new File(c.getFilesDir(),"creator-signing");folder.mkdirs();prefs=c.getSharedPreferences("game-apk-versions",0);}
static void check(String id)throws IOException{if(id==null||!id.matches("[a-zA-Z0-9_-]{1,100}"))throw new IOException("게임 ID 형식");}
KeyStore androidKeys()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);return ks;}
CreatorKeys legacy()throws Exception{KeyStore ks=androidKeys();String a="event-game-export-v1";return ks.containsAlias(a)?new CreatorKeys((PrivateKey)ks.getKey(a,null),(X509Certificate)ks.getCertificate(a)):null;}
String fingerprint(X509Certificate c)throws Exception{return Base64.encodeToString(MessageDigest.getInstance("SHA-256").digest(c.getEncoded()),Base64.NO_WRAP);}
javax.crypto.SecretKey wrapping()throws Exception{KeyStore ks=androidKeys();String a="event-creator-wrap-v1";if(!ks.containsAlias(a)){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(a,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return (javax.crypto.SecretKey)ks.getKey(a,null);}
byte[] unseal(File f)throws Exception{JSONObject p=new JSONObject(new String(Files.readAllBytes(f.toPath()),StandardCharsets.UTF_8));Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,wrapping(),new GCMParameterSpec(128,Base64.decode(p.getString("iv"),Base64.DEFAULT)));return c.doFinal(Base64.decode(p.getString("data"),Base64.DEFAULT));}
void seal(File f,byte[] bytes)throws Exception{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,wrapping());JSONObject p=new JSONObject();p.put("iv",Base64.encodeToString(c.getIV(),Base64.NO_WRAP));p.put("data",Base64.encodeToString(c.doFinal(bytes),Base64.NO_WRAP));PartitionStore.atomic(f,p.toString());}
JSONObject marker(String id)throws Exception{File f=new File(folder,id+".legacy");return f.exists()?new JSONObject(new String(Files.readAllBytes(f.toPath()),StandardCharsets.UTF_8)):null;}
synchronized CreatorKeys get(String id,boolean create)throws Exception{check(id);File f=new File(folder,id+".key");if(f.exists())return CreatorKeys.decode(unseal(f));CreatorKeys old=legacy();JSONObject m=marker(id);if(m!=null){if(old==null||!m.getString("fingerprint").equals(fingerprint(old.cert)))throw new IOException("이 게임은 이전 휴대폰의 서명이 필요합니다. 기존 폰에서 업데이트하거나 새 게임으로 복제하세요.");return old;}if(old!=null&&prefs.contains(ApkExportEngine.packageName(id,old.cert)))return old;if(!create)return null;CreatorKeys k=CreatorKeys.generate();seal(f,k.encode());return k;}
synchronized String info(String id)throws Exception{CreatorKeys k=get(id,false);JSONObject p=new JSONObject();p.put("mode",new File(folder,id+".key").exists()?"portable":k!=null?"legacy":"none");if(k!=null){String pkg=ApkExportEngine.packageName(id,k.cert);p.put("package",pkg);p.put("version",prefs.getInt(pkg,0));p.put("backedUp",context.getSharedPreferences("creator-backups",0).getBoolean(pkg,false));}return p.toString();}
synchronized String backup(String id)throws Exception{CreatorKeys k=get(id,true);boolean portable=new File(folder,id+".key").exists();JSONObject p=new JSONObject();String pkg=ApkExportEngine.packageName(id,k.cert);p.put("mode",portable?"portable":"legacy");p.put("package",pkg);p.put("fingerprint",fingerprint(k.cert));p.put("version",prefs.getInt(pkg,0));if(portable)p.put("key",Base64.encodeToString(k.encode(),Base64.NO_WRAP));return p.toString();}
synchronized boolean restore(String id,String raw,int latest)throws Exception{check(id);JSONObject p=new JSONObject(raw);int version=p.getInt("version");if(version<0||latest<0||latest==Integer.MAX_VALUE)throw new IOException("배포 버전 형식");String pkg=p.getString("package"),fp=p.getString("fingerprint");CreatorKeys existing=null;try{existing=get(id,false);}catch(Exception ignored){}if(existing!=null&&!fp.equals(fingerprint(existing.cert)))throw new IOException("같은 게임 ID에 다른 배포 서명이 있습니다. 기존 게임을 덮어쓰지 않습니다.");
if(p.getString("mode").equals("portable")){byte[] bytes=Base64.decode(p.getString("key"),Base64.DEFAULT);if(bytes.length>20000)throw new IOException("배포 키 크기");CreatorKeys k=CreatorKeys.decode(bytes);if(!fp.equals(fingerprint(k.cert))||!pkg.equals(ApkExportEngine.packageName(id,k.cert)))throw new IOException("배포 서명 정보가 일치하지 않습니다.");seal(new File(folder,id+".key"),bytes);}else if(p.getString("mode").equals("legacy")){if(!pkg.matches("com\\.eventvn\\.play\\.g[a-f0-9]{64}"))throw new IOException("앱 ID 형식");PartitionStore.atomic(new File(folder,id+".legacy"),p.toString());}else throw new IOException("배포 백업 형식");return prefs.edit().putInt(pkg,Math.max(prefs.getInt(pkg,0),Math.max(version,latest))).commit();}
}
